 public void AdvanceOrganisationsG(){if(Organisations.LastTick==default){Organisations.LastTick=Now;return;}DateTime from=Organisations.LastTick;decimal hours=(decimal)Math.Max(0,(Now-Organisations.LastTick).TotalHours);Organisations.LastTick=Now;
  foreach(var s in Organisations.Structures){if(s.State=="Anchoring"&&s.Due<=Now){s.State=s.Fuel>0?"Online":"Low power";s.UnpoweredSince=s.Due;if(s.Kind=="Refinery"){var f=new FacilityE{Station=s.Station,Kind="Refinery",Online=s.State=="Online"};Production.Facilities.Add(f);s.Facility=f.Id;}}
   if(s.State=="Online"){DateTime poweredFrom=s.Due>from&&s.Due<=Now?s.Due:from;decimal usable=(decimal)Math.Max(0,(Now-poweredFrom).TotalHours);decimal used=Math.Min(s.Fuel,usable);s.Fuel-=used;if(s.Kind=="Skyhook")s.Stock+=used*10;if(s.Fuel==0){s.State="Low power";s.UnpoweredSince=poweredFrom.AddHours((double)used);}}
   if(s.State=="Low power"&&s.UnpoweredSince.AddDays(7)<=Now)s.State="Abandoned";
   if(s.State=="Reinforced"&&s.Due<=Now)s.State="Vulnerable";
   s.Capacitor=RechargeBridgeG(s.Capacitor,(double)hours);
   if(s.Facility!=""){var f=Production.Facilities.FirstOrDefault(f=>f.Id==s.Facility);if(f!=null)f.Online=s.State=="Online";}
   if(s.State=="Unanchoring"&&s.Due<=Now){s.State="Recovered";SettleStructureG(s,false);}
  }
  AdvanceNpcCampaignsG();
  foreach(var o in Organisations.Operations.Where(o=>o.State=="Active"&&o.Due<=Now).OrderBy(o=>o.Due)){o.State="Resolved";var c=Organisations.Corps.FirstOrDefault(c=>c.Id==o.Corp);if(c==null){o.State="Failed";continue;}
   if(o.Kind is "Siege" or "Robbery"){var s=Organisations.Structures.FirstOrDefault(s=>s.Id==o.Target);if(s==null||s.State is "Destroyed" or "Recovered"){o.State="Failed";continue;}if(o.Kind=="Robbery"){decimal loot=Math.Min(100,s.Stock);s.Stock-=loot;c.Goods["ore"]=c.Goods.GetValueOrDefault("ore")+loot;if(c.Id==Organisations.PlayerCorp)Organisations.SuspectUntil=Now.AddMinutes(15);}
