   else {var t=Organisations.Territories.First(t=>t.System==o.Target);if(o.Kind=="Claim"){if(t.Attacker!=c.Id){t.Attacker=c.Id;t.Capture=0;}t.Capture+=25;if(t.Capture>=100){t.Owner=c.Id;t.Attacker="";t.Capture=0;LogG("Territorial ownership transferred / "+t.System);}}if(o.Kind=="Plex"){if(t.Militia!=c.Id)t.MilitiaCapture=0;t.MilitiaCapture=Math.Min(100,t.MilitiaCapture+25);t.Militia=c.Id;WalletRewardG(c,100);}if(o.Kind=="Piracy")t.Corruption=Math.Min(100,t.Corruption+25);if(o.Kind=="Suppress")t.Suppression=Math.Min(100,t.Suppression+25);}
   LogG(o.Kind+" / "+o.State+" / "+o.Id);
  }
  foreach(var t in Organisations.Territories){var sky=Organisations.Structures.Where(s=>s.System==t.System&&s.Corp==t.Owner&&s.State=="Online"&&s.Kind=="Skyhook").ToArray();t.Power=sky.Length*100;t.Workforce=sky.Length*100;t.Commodity=sky.Sum(s=>s.Stock);t.Upgrade=t.Owner!=""&&t.Power>=100&&t.Workforce>=100&&t.Commodity>=10;foreach(var s in sky){if(t.Upgrade){decimal consume=Math.Min(s.Stock,hours);s.Stock-=consume;}}t.Front=t.Corruption>t.Suppression?"Frontline":t.Militia!="Neutral"?"Command":"Rearguard";}
 }
