 void SettleStructureG(StructureG s,bool destroyed){if(s.Settled)return;s.Settled=true;if(s.Facility!="")DestroyFacilityE(s.Facility);if(s.Assets.Count>0){bool drops=destroyed&&(s.UnpoweredSince!=default&&s.UnpoweredSince.AddDays(7)<=Now||ResolveSystem43(s.System).Id.StartsWith("system:31"));Organisations.Safety.Add(new(){Corp=s.Corp,Destination=s.Station,State=drops?"Dropped":"Locked",Due=Now.AddDays(destroyed?20:0),Fee=destroyed&&!drops?s.Assets.Sum(a=>a.Value)*.15m:0,Assets=new(s.Assets)});s.Assets.Clear();}LogG("Storage settled once / "+s.Name);}
