 public string ConfigureBridgeG(string id,string system){var s=Organisations.Structures.FirstOrDefault(s=>s.Id==id);var c=CorporationG;if(s==null||c==null||s.Corp!=c.Id||s.Kind!="Bridge"||!HasRoleG("Station Manager")||c.Alliance==""||system==s.System||!Organisations.Territories.Any(t=>t.System==system&&t.Owner==c.Id))return "Bridge management, an alliance and owned destination required.";if(BeaconDistance(s.System,system)>5)return "Bridge span exceeds five light-years.";s.Destination=system;return "";}
