 public string TransitBridgeG(string id){if(InHubH)return "Bridge travel unavailable in restricted hub.";var s=Organisations.Structures.FirstOrDefault(s=>s.Id==id);var c=CorporationG;if(s==null||c==null||Docked||s.System!=SystemId||s.Kind!="Bridge"||s.State!="Online"||s.Destination==""||s.Corp!=c.Id||c.Alliance==""||Player.CombatHull is "dread" or "carrier" or "super" or "titan"||!CanUseGate("player")||!Organisations.Structures.Any(b=>b.Kind=="Bridge"&&b.System==s.Destination&&b.Corp==c.Id&&b.State=="Online"&&b.Destination==s.System))return "Undock an eligible subcapital; a paired online alliance bridge is required.";if(!Organisations.Territories.Any(t=>t.System==s.System&&t.Owner==c.Id&&t.Upgrade)||!Organisations.Territories.Any(t=>t.System==s.Destination&&t.Owner==c.Id&&t.Upgrade))return "Territorial resource shortfall disables the logistics network.";if(s.PhysicalQ&&(s.CellQ!=SolarGridKey||(s.AnchorQ-SystemPosition).Length>2500||!TravelInterlockQ(true)||RobbingQ||!Organisations.Structures.Any(b=>b.PhysicalQ&&b.Kind=="Bridge"&&b.System==s.Destination&&b.Destination==s.System&&b.Corp==s.Corp&&b.State=="Online")))return "Approach a paired physical bridge within 2,500 m with elapsed legal timers.";decimal? basis=BridgeHullCostG();if(basis==null)return "Hull class has no approved bridge admission profile.";decimal cost=BridgeCostG(s.Destination,c.Capital,basis.Value);if(s.Capacitor<cost)return "Bridge capacitor depleted.";s.Capacitor-=cost;SystemId=s.Destination;StationId="";EnterGrid("deep_space",false);if(s.PhysicalQ){var exit=Organisations.Structures.First(b=>b.PhysicalQ&&b.Kind=="Bridge"&&b.System==SystemId&&b.Destination==s.System&&b.Corp==s.Corp&&b.State=="Online");EnterDeepSpace(exit.AnchorQ);BindStructuresQ();}return "";}
 public decimal? BridgeHullCostG(){if(Commander.Capsule)return 1;var h=CombatHulls.Get(Player.CombatHull);string role=h.Role;decimal? roleCost=role switch{"Industrial" or "MiningBarge" or "Exhumer" or "ExpeditionFrigate" or "Freighter" or "JumpFreighter"=>1,"CovertOps"=>5,"Destroyer"=>6,"AssaultFrigate" or "BlockadeRunner" or "DeepTransport"=>7,"Interceptor"=>8,"Interdictor"=>8.5m,"CommandDestroyer" or "ElectronicAttack" or "LogisticsFrigate" or "TacticalDestroyer"=>9,"MiningTender"=>10,"HeavyInterdictor"=>10.5m,"Bomber"=>11,"ForceRecon" or "CombatRecon" or "HeavyAssault"=>11.5m,"Logistics" or "AdaptiveLogistics"=>12.5m,"StrategicCruiser"=>13,"AttackBattlecruiser"=>14,"Battlecruiser"=>14.5m,"ExpeditionCommand"=>15,"Command"=>16.5m,"BlackOps"=>18,"Marauder" or "CapitalIndustrial"=>19,_=>null};if(roleCost!=null)return roleCost;string cls=FleetCatalog.ById.TryGetValue(Player.CombatHull,out var ship)?ship.Class:Player.CombatHull;return cls switch{"Capsule" or "Shuttle" or "Corvette" or "Freighter" or "Jump Freighter" or "Hauler" or "Mining Barge" or "Exhumer" or "Expedition Frigate"=>1,"Frigate" or "frigate"=>4,"Destroyer" or "destroyer"=>6,"Cruiser" or "cruiser"=>10,"Combat Battlecruiser" or "battlecruiser"=>14.5m,"Attack Battlecruiser"=>14,"Battleship" or "battleship"=>16.5m,"Capital Industrial Ship"=>19,_=>null};}
 public static decimal BridgeCostG(string destination,string capital,decimal hullCost){double distance=destination==capital?0:BeaconDistance(destination,capital);decimal multiplier=distance<=5?0:distance<=10?2:distance<=15?6:distance<=20?9:15;return hullCost*multiplier;}
 public static decimal RechargeBridgeG(decimal current,double hours){if(hours<=0)return current;double fraction=Math.Clamp((double)current/1250,0,1);double root=Math.Sqrt(fraction);double result=1-(1-root)*Math.Exp(-5*hours/6.25);return (decimal)Math.Clamp(1250*result*result,0,1250);}
 void AdvanceNpcCampaignsG(){if(!Organisations.Autonomous||Organisations.NextNpcDecision>Now)return;Organisations.NextNpcDecision=Now.AddHours(1);foreach(var npc in Organisations.Corps.Where(c=>c.Npc&&c.Wallets[0]>=500)){string business=npc.Id.StartsWith("npc:")?npc.Id[4..]:"";var seen=Population.Pilots.Where(p=>p.Company==business&&p.Fit.Hull>0&&p.Status!="Lost").Select(p=>p.System).ToHashSet();var target=Organisations.Structures.FirstOrDefault(s=>s.Corp!=npc.Id&&seen.Contains(s.System)&&s.State is not("Destroyed" or "Recovered" or "Reinforced")&&(Organisations.Corps.FirstOrDefault(c=>c.Id==s.Corp)?.Treaties.GetValueOrDefault(npc.Id)=="Hostile"||Organisations.Wars.Any(w=>w.Starts<=Now&&w.Ends>Now&&((w.A==npc.Id&&w.B==s.Corp)||(w.B==npc.Id&&w.A==s.Corp))))&&!Organisations.Operations.Any(o=>o.Target==s.Id&&o.State=="Active"));if(target==null||target.PhysicalQ)continue;npc.Wallets[0]-=500;Organisations.Operations.Add(new(){Corp=npc.Id,Kind="Siege",Target=target.Id,Due=Now.AddHours(1)});LogG("Observed local mobilisation / "+npc.Name+" / finite 500 CR commitment");}}
 public static void ValidateOrganisationsG(OrganisationStateG? g){if(g==null)return;if(g.Corps==null||g.Structures==null||g.Operations==null||g.Territories==null||g.Projects==null||g.Wars==null||g.Safety==null||g.Journal==null)throw new InvalidDataException("Incomplete organisation save.");if(g.Corps.Any(c=>c==null||c.Wallets==null||c.Wallets.Length!=7||c.Wallets.Any(x=>x<0)||c.Tax<0||c.Tax>1||c.Members==null||c.Goods==null||c.Treaties==null)||g.Structures.Any(s=>s==null||s.Access==null||s.State is not("Anchoring" or "Online" or "Low power" or "Abandoned" or "Reinforced" or "Vulnerable" or "Unanchoring" or "Recovered" or "Destroyed")||s.Kind is not("Citadel" or "Refinery" or "Skyhook" or "Bridge")||s.Fuel<0||s.Stock<0||s.Capacitor<0||s.Capacitor>1250||s.Assets==null||s.Assets.Any(a=>a.Value<0))||g.Projects.Any(p=>p==null||p.Escrow<0||p.Delivered<0||p.Delivered>p.Goal)||g.Safety.Any(a=>a==null||a.Fee<0||a.Assets==null||a.Assets.Any(k=>k.Value<0)||a.State is not("Locked" or "Dropped" or "Recovered"))||g.Operations.Any(o=>o==null||o.Cost<0||o.State is not("Active" or "Resolved" or "Failed")||o.Kind is not("Siege" or "Claim" or "Plex" or "Piracy" or "Suppress" or "Robbery"))||g.Territories.Any(t=>t==null||t.Capture<0||t.Corruption<0||t.Corruption>100||t.Suppression<0||t.Suppression>100)||g.Operations.Select(o=>o.Id).Distinct().Count()!=g.Operations.Count||g.Projects.Select(o=>o.Id).Distinct().Count()!=g.Projects.Count||g.Safety.Select(o=>o.Id).Distinct().Count()!=g.Safety.Count||g.Corps.Select(c=>c.Id).Distinct().Count()!=g.Corps.Count||g.Structures.Select(s=>s.Id).Distinct().Count()!=g.Structures.Count)throw new InvalidDataException("Invalid organisation accounting.");}
